// Kaleidoscopic IFS - color only, ANIMATED. Runs INSIDE shadeSurface().
// A kaleidoscopic iterated function system (Knighty's KIFS): fold space into one
// wedge of a cube's symmetry (abs + sorting of the coordinates), turn it a little,
// scale it about a corner -- and repeat. Points of the attractor stay close to the
// corner; the others are flung away. The surface cuts this crystal: facets, nested
// triangles and squares at every scale. The turn angle drifts with time, so the
// crystal slowly reorganizes itself.
// No displacement: one evaluation per pixel, cheap at any resolution.
// In scope: pModel, t. Dock colors: u_col1 = light facets, u_col2 = deep tone.

float ZOOM  = 1.3 * max(E, 0.05);   // slider E   // size of the crystal     [0.5 .. 3]
float TURN  = 0.08 * F;             // slider F   // turning speed           [0 .. 0.4]
float SCALE = 2.0;                  // scale of each fold                    [1.8 .. 2.4]
vec3  OFFS  = vec3(1.0, 0.9, 0.8);  // the corner the folds scale about
const int ITER = 9;

float ang = 0.25 + 0.15 * sin(TURN * t);
float ca = cos(ang);
float sa = sin(ang);
// rotation about the (1,1,1) diagonal: Rodrigues' formula, written out
vec3  ax = vec3(0.57735);
mat3  rot = mat3(ca) + sa * mat3(0.0, ax.z, -ax.y,  -ax.z, 0.0, ax.x,  ax.y, -ax.x, 0.0)
          + (1.0 - ca) * mat3(ax.x * ax, ax.y * ax, ax.z * ax);

vec3 z = pModel * ZOOM;
vec4 trap = vec4(1e9);
for (int i = 0; i < ITER; i++) {
    z = abs(z);
    if (z.x < z.y) z.xy = z.yx;
    if (z.x < z.z) z.xz = z.zx;
    if (z.y < z.z) z.yz = z.zy;
    z = rot * z;
    z = z * SCALE - OFFS * (SCALE - 1.0);
    trap = min(trap, vec4(abs(z), dot(z, z)));
}
// distance to the attractor (the classic KIFS estimate), back in model units
float de = (length(z) - 1.5) * pow(SCALE, -float(ITER)) / ZOOM;

// facets colored by the orbit trap: orbits that stay near the corner (small trap)
// are the crystal, in the palette; the ones flung away sink toward u_col2
vec3 pal = 0.5 + 0.5 * cos(6.2832 * (vec3(0.0, 0.2, 0.45) + 0.6 * sqrt(trap.xyz)));
float far = clamp(0.3 * log(1.0 + trap.w), 0.0, 1.0);
vec3 col = mix(ubuf.u_col1 * (0.45 + 0.85 * pal), ubuf.u_col2, far);
// bright edges where the surface passes close to the attractor
col += ubuf.u_col1 * 0.8 * (1.0 - smoothstep(0.0, 0.006, abs(de)));
col *= 0.75 + 0.25 * smoothstep(0.0, 0.05, abs(de));

textureCol = col;
